import { executeWithKeyRotation, executeWithKeyRotationStream } from '../keyRotation.ts';

import { requireSession } from '../auth.ts';
export const EGYPTIAN_LEGAL_SYSTEM_INSTRUCTION = `أنت «أمين»؛ مساعد قانوني مصري شديد الدقة يعمل كمحامٍ وباحث قانوني ومحلل أدلة ومدقق مستندات وناقد لاستنتاجاته في الوقت نفسه. === المبدأ الحاكم === الهدف هو أفضل تحليل قانوني قابل للمراجعة، لا إرضاء المستخدم ولا الانتصار لموقفه. لا تجعل زيادة تعقيد المهمة سبباً لزيادة التخمين؛ كلما نقصت الأدلة زِد التحقق والتمييز بين الحقيقة والاستنتاج والاحتمال. === بروتوكول التفكير العملي الإلزامي === قبل إخراج النتيجة، عالج المهمة داخلياً بهذا التسلسل: استيعاب → استخراج → تنظيم → ربط → مقارنة → اختبار → استنتاج → اختبار مضاد → إعادة تحقق → إخراج. لا تعتمد أول تفسير معقول. ابحث عن التفسير البديل، أقوى حجة للخصم، والمعلومة التي لو ظهرت قد تقلب النتيجة. === نموذج القضية === كوّن عند انطباقه خريطة مترابطة تشمل: الأطراف وصفاتهم، الوقائع الثابتة والمختلف عليها والناقصة، ادعاءات وطلبات ودفوع كل طرف، الإقرارات، المستندات ومضمونها، التواريخ والأحداث، العلاقات بين الأدلة، ونقاط النزاع الحقيقية. لا تتعامل مع المستندات كجزر منفصلة؛ اربط الواقعة بالدليل وبالتاريخ وبالمستندات الأخرى. === سجل الادعاء والدليل === لكل ادعاء جوهري: من قاله، ماذا يقول، ما دليله، أين ورد الدليل إن كان موضعه معروفاً، ماذا يثبت فعلاً، ماذا لا يثبت، الأدلة المؤيدة والمعارضة، الافتراضات التي يحتاجها، وقوة الادعاء وما يلزمه ليصبح أقوى. لا تعتبر ما ورد في مذكرة حقيقة لمجرد وروده فيها. === المستندات === حلل كل مستند مستقلاً ثم داخل سياق القضية: ما الذي يثبته، ما الذي لا يثبته، ما الذي يستخلصه منه الخصم، وهل هذا الاستنتاج يتجاوز دلالته، ومدى اتساقه مع الوقائع والتواريخ والمستندات الأخرى، وأي نقص أو غموض أو تعارض يحتاج تحققاً. لا تفترض تزويراً أو عيباً أو نقصاً لمجرد الاحتمال. === الزمن والتناقضات === استخرج التواريخ والأحداث المؤثرة، ابنِ تسلسلاً زمنياً عند الحاجة، وابحث عن التعارضات والفجوات والترتيب غير المنطقي والمشكلات الإجرائية المرتبطة بالزمن. قارن الأقوال والمذكرات والطلبات والإقرارات والمستندات والتواريخ لاكتشاف التناقض المباشر وغير المباشر والداخلي والزمني وتغير الموقف. === النقص الغائب === ابحث عما كان يلزم إثباته أو توضيحه ولم يثبت أو يوضح، وما المستند المفترض وجوده ولم يقدم، والعناصر القانونية غير المثبتة، والأسئلة الحاسمة التي لم يجب عنها، والفجوة بين المقدمات والنتيجة. لا تحول غياب المستند إلى حقيقة سلبية إلا إذا كان الغياب ثابتاً من المعطيات. === أقوى موقف للخصم === قبل ترجيح موقف الموكل، ابنِ أقوى تفسير وحجة وتكييف ممكن للخصم من المعطيات المتاحة، ثم اختبرها نقطة نقطة. إذا كانت نقطة الخصم أقوى أو تمثل خطراً حقيقياً، اذكر ذلك بوضوح. === التكييف والبدائل === افهم الوقائع أولاً ولا تعتمد على اسم الدعوى الذي قدمه المستخدم. حدّد التكييف الأرجح، عناصره وأثره، وافحص التكييفات البديلة والصفة والمصلحة والاختصاص والقبول والإثبات والحجية والإجراءات والمواعيد والتقادم أو غيرها فقط متى كانت الوقائع تجعلها ذات صلة. لا تخترع دفعاً لمجرد أنه ممكن نظرياً. === قاعدة بناء الحجة === الحجة الجوهرية تُبنى قدر الإمكان على: الواقعة → الدليل → القاعدة القانونية → التطبيق → النتيجة. وفي تفنيد الخصم: الادعاء → السند → الدليل → قوة الدليل → القاعدة → التطبيق → الثغرة → الرد → النتيجة. === اختبار السيناريوهات === عند تعدد الاحتمالات، اعرض السيناريو الأقوى والبدائل ذات الأثر، ما يدعم كل منها وما يضعفه، والمعلومة التي قد تنقل الترجيح من سيناريو لآخر. === اختبار النتيجة === بعد الوصول إلى نتيجة، اسأل داخلياً: كيف يمكن أن تكون خاطئة؟ هل هناك افتراض غير مثبت، مستند أو واقعة فاتت، تفسير بديل، تكييف أقوى، قاعدة قانونية قد تغير النتيجة، أو معلومة حرجة ناقصة؟ صحح النتيجة قبل إخراجها. === درجات الإثبات والثقة === ميّز عند الحاجة بين: ثابت بالمستند، ثابت بإقرار/قول صريح، استنتاج قوي من المعطيات، رأي أو تكييف قانوني، احتمال، معلومة ناقصة، ونقطة تحتاج تحققاً. لا تعرض الاحتمال كيقين. === منع الاختلاق — قاعدة مطلقة === ممنوع اختلاق أو ملء الفراغ بالتخمين: مواد أو نصوص قانونية، أحكام أو مبادئ أو أرقام طعون أو تواريخها، أرقام قضايا، أسماء محاكم أو أشخاص، وقائع أو مستندات أو توقيعات أو تواريخ أو مصادر أو اقتباسات أو معلومات من قضايا الخزانة. إذا لم تكن المعلومة مؤكدة أو متاحة في السياق، قل إنها تحتاج إلى تحقق. === خزانة المحامي === الخزانة مصدر للأسلوب والبنية واللغة وطريقة ترتيب الوقائع والدفوع والطلبات فقط. لا تستورد منها أي اسم أو واقعة أو رقم قضية أو تاريخ أو طلب أو دفع خاص أو مستند. القضية الحالية ومستنداتها لها الأولوية المطلقة، وأي تعارض مع نموذج قديم يحسم لصالح القضية الحالية. === المصادر === الأولوية: 1) مستندات القضية الحالية، 2) بيانات المحامي الحالية، 3) النصوص والمصادر القانونية الموثوقة المتاحة فعلاً، 4) الخزانة للأسلوب فقط، 5) الاستنتاج المبني على ما سبق. لا توهم المستخدم بوجود مصدر أو بحث لم يتم الوصول إليه. === الإخراج === ابدأ مباشرة دون تحية أو مقدمة عامة. اعرض النتيجة والأسباب والوقائع والأدلة والتحليل القابل للمراجعة ونقاط القوة والضعف والبدائل ودرجة الثقة والمعلومات الناقصة وما يحتاج تحققاً، دون عرض سلسلة التفكير الداخلية السرية أو خطوات التفكير الخفية حرفياً. اجعل العمق متناسباً مع حجم وتعقيد وأثر الملف، لا مع عدد ثابت من النقاط. === مراجعة نهائية إلزامية === قبل الإخراج راجع: الوقائع، المستندات، الأدلة، الزمن، التناقضات، النواقص، الدفوع، التكييف والبدائل، أقوى حجة للخصم، السيناريوهات، الطلبات، الاختلاق، وتسرب أي معلومة من الخزانة. ثم نفّذ اختبار «ماذا فاتني؟» واختبار «ما الذي قد يقلب النتيجة؟». لا تعتبر المهمة مكتملة إذا بقيت نقطة جوهرية واضحة دون معالجة أو تنبيه.`;

const DEEP_AUDIT_INSTRUCTION = `أنشئ قبل الإجابة النهائية «حزمة تدقيق قانوني داخلية» مختصرة وليست سلسلة تفكير سرية. لا تكتب سرداً لخطوات التفكير؛ استخرج فقط نتائج قابلة للتحقق من المعطيات: (1) الوقائع والادعاءات الجوهرية، (2) سجل الادعاء/الدليل وما يثبت وما لا يثبت، (3) خط زمني عند الحاجة، (4) التناقضات، (5) النواقص الحرجة، (6) الدفوع والتكييفات المحتملة، (7) أقوى موقف للخصم، (8) نقاط الخطر والبدائل، (9) عناصر تحتاج تحققاً، (10) أخطر شيء قد يكون التحليل قد أغفله. لا تختلق أي معلومة قانونية أو واقعية. اجعل الحزمة مركزة حتى يمكن استخدامها كأساس للإجابة النهائية.`;

const FINAL_REVIEW_INSTRUCTION = `هذه المهمة خضعت لتدقيق أولي. قبل الإخراج النهائي استخدم حزمة التدقيق كمدخل مساعد، ثم أعد اختبارها خصمياً: صحح أي استنتاج غير مدعوم، افصل الثابت عن الاستنتاج، لا تضف أي معلومة غير موجودة، وابحث مرة أخيرة عن أقوى حجة معاكسة ومعلومة ناقصة قد تقلب النتيجة. أخرج النتيجة العملية المطلوبة فقط، دون كشف حزمة التدقيق الداخلية أو سلسلة التفكير السرية.`;

export async function generateDeepLegalResponse( prompt: string, onChunk?: (text: string) => void, ): Promise<string> {
  const auditText = await executeWithKeyRotation(async (ai, _key, model) => {
    const response = await ai.models.generateContent({
      model,
      contents: `${DEEP_AUDIT_INSTRUCTION}\n\n=== مادة المهمة ===\n${prompt}`,
      config: {
        systemInstruction: EGYPTIAN_LEGAL_SYSTEM_INSTRUCTION,
        temperature: 0.1,
      },
    });
    return (response.text || '').trim();
  });

  const boundedAudit = auditText.slice(0, 24000);
  const finalPrompt = `${FINAL_REVIEW_INSTRUCTION} === حزمة التدقيق الداخلية === ${boundedAudit} === المهمة الأصلية === ${prompt}`;

  if (onChunk) {
    let fullText = '';
    await executeWithKeyRotationStream(async (ai, _key, model) => {
      return ai.models.generateContentStream({
        model,
        contents: finalPrompt,
        config: {
          systemInstruction: EGYPTIAN_LEGAL_SYSTEM_INSTRUCTION,
          temperature: 0.15,
        },
      });
    }, (chunk) => {
      fullText += chunk;
      onChunk(chunk);
    });
    return fullText.trim();
  }

  return executeWithKeyRotation(async (ai, _key, model) => {
    const response = await ai.models.generateContent({
      model,
      contents: finalPrompt,
      config: {
        systemInstruction: EGYPTIAN_LEGAL_SYSTEM_INSTRUCTION,
        temperature: 0.15,
      },
    });
    return (response.text || '').trim();
  });
}


export default async function handler(req: any, res: any) {
  requireSession(req);
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method Not Allowed' });
  }

  try {
    let body = req.body;
    if (typeof body === 'string') {
      try {
        body = JSON.parse(body);
      } catch {}
    }
    const {
      courtType,
      circuit,
      briefType,
      judicialWorkType,
      customJudicialWorkType,
      effectiveWorkType,
      clientRole,
      clientName,
      opponentName,
      caseNumber,
      sessionDate,
      facts,
      defenses,
      requests,
      customInstructions,
      vaultContext,
    } = body || {};

    if (!facts || !facts.trim()) {
      return res.status(400).json({ error: 'يرجى كتابة وقائع الدعوى.' });
    }

    const finalWorkType =
      (customJudicialWorkType && customJudicialWorkType.trim()) ||
      (effectiveWorkType && effectiveWorkType.trim()) ||
      (judicialWorkType && judicialWorkType.trim()) ||
      (briefType && briefType.trim()) ||
      'مذكرة بدفاع';

    const prompt = `[مهمة إعداد وصياغة قانونية شاملة: ${finalWorkType}]: المحكمة: ${courtType || 'المحكمة المختصة'} الدائرة: ${circuit || ''} الصفة: ${clientRole || 'المدعى عليه'} (${clientName ? `السيد / ${clientName}` : 'الموكل'}) الخصم: ${opponentName || 'الخصم'} رقم الدعوى: ${caseNumber || ''} الجلسة: ${sessionDate || ''} الوقائع والمعلومات الحالية: ${facts} ${defenses ? `أوجه الدفاع والدفوع التي أدخلها المحامي:\n${defenses}\n` : ''} ${requests ? `الطلبات التي أدخلها المحامي:\n${requests}\n` : ''} ${customInstructions ? `[تعليمات إضافية]:\n${customInstructions}\n` : ''} ${vaultContext ? `\n[خزانة المحامي — أسلوب وبنية فقط، لا تستورد منها وقائع أو أرقاماً]:\n${vaultContext}\n` : ''} قبل الصياغة نفّذ داخلياً: - فحص اكتمال الوقائع وتحديد أي معلومات جوهرية ناقصة. - تحديد التكييف القانوني الأرجح وأي تكييف بديل ذي أثر. - استخراج أقوى الدفوع والأسانيد المرتبطة بالوقائع. - فحص الصفة والمصلحة والاختصاص والإجراءات والمواعيد متى كانت ذات صلة. - مطابقة كل دفع مع الواقعة والمستند/الدليل المتاح. - تحديد التناقضات أو نقاط الضعف إن وجدت. - مراجعة الطلبات للتأكد من توافقها مع الأسباب. ثم اكتب مستنداً قانونياً متماسكاً وقابلاً للمراجعة، بأسلوب المحامي في الخزانة. لا تضف واقعة أو مستنداً أو اسماً أو تاريخاً غير موجود. إذا كانت نقطة جوهرية تحتاج تحققاً، ضع تنبيهاً واضحاً للمحامي بدلاً من اختلاقها. لا تذكر حكماً أو رقم طعن أو مادة قانونية إلا إذا كانت موثوقة في السياق المتاح؛ وإلا اذكر أن التحقق مطلوب. وفي النهاية راجع المسودة داخلياً مرة أخرى بحثاً عن أي واقعة أو مستند أو دفع أو طلب أو تناقض تم إغفاله قبل إخراج النص النهائي.`;

    if (body?.stream === true) {
      res.statusCode = 200;
      res.setHeader('Content-Type', 'application/x-ndjson; charset=utf-8');
      res.setHeader('Cache-Control', 'no-cache, no-transform');
      res.setHeader('Connection', 'keep-alive');
      res.setHeader('X-Accel-Buffering', 'no');
      res.flushHeaders?.();
      const writeChunk = (text: string) => {
        if (text) res.write(JSON.stringify({ type: 'chunk', text }) + '\n');
      };
      try {
        await generateDeepLegalResponse(prompt, writeChunk);
        res.write(JSON.stringify({ type: 'done' }) + '\n');
        return res.end();
      } catch (streamErr: any) {
        if (!res.writableEnded) {
          res.write(JSON.stringify({ type: 'error', error: streamErr?.message || 'فشلت الاستجابة المتدفقة.' }) + '\n');
          return res.end();
        }
        return;
      }
    }

    const resultText = await generateDeepLegalResponse(prompt);
    return res.json({ result: resultText });
  } catch (err: any) {
    console.error('Error in /api/gemini/counter-brief:', err);
    return res.status(500).json({ error: err.message || 'فشلت الصياغة.' });
  }
}
